/* Iberia Ferroviaria 2.0 — interfaz de papel y esmalte sobre el mapa. */
@font-face{font-family:Fraunces;src:url('data:font/woff2;base64,') format('woff2');font-weight:100 900;font-display:swap}
@font-face{font-family:Figtree;src:url('data:font/woff2;base64,') format('woff2');font-weight:300 900;font-display:swap}
@font-face{font-family:'IBM Plex Mono';src:url('data:font/woff2;base64,') format('woff2');font-weight:500;font-display:swap}
:root{
 --paper:#f7f0e1;--paper-2:#efe5cf;--paper-3:#e6d9bc;--ink:#2a221c;--ink-2:#5d5143;--ink-3:#8a7c69;--rule:rgba(74,56,36,.16);--rule-2:rgba(74,56,36,.28);
 --wine:#8a2a46;--wine-2:#a8385a;--gold:#c98a1c;--gold-2:#f0b544;--green:#3f7d4e;--red:#c23b2f;--blue:#2f6f9f;
 --hud:rgba(250,244,230,.9);--hud-ink:#2a221c;--shadow:0 18px 50px rgba(52,34,20,.22),0 2px 8px rgba(52,34,20,.12);
 --serif:Fraunces,Georgia,'Times New Roman',serif;--sans:Figtree,'Segoe UI',system-ui,sans-serif;--mono:'IBM Plex Mono',ui-monospace,Consolas,monospace;
 --rail-w:84px;--radius:14px
}
body[data-sky=night]{--hud:rgba(20,22,36,.86);--hud-ink:#f3e7cc}
*{box-sizing:border-box}
html,body{margin:0;height:100%;overflow:hidden;background:#2a1f1c;color:var(--ink);font:15px/1.5 var(--sans);-webkit-font-smoothing:antialiased}
button,input,select{font:inherit;color:inherit}
a{color:var(--wine)}
#game{position:fixed;inset:0;overflow:hidden}
#map{position:absolute;inset:0;width:100%;height:100%;touch-action:none;cursor:grab;background:#6f9fa8}
.hidden{display:none!important}
.mono{font-family:var(--mono);font-variant-numeric:tabular-nums}

/* HUD superior */
.hud{position:absolute;top:12px;left:calc(var(--rail-w) + 14px);right:14px;display:flex;align-items:center;gap:26px;padding:10px 18px;background:var(--hud);color:var(--hud-ink);border-radius:18px;box-shadow:var(--shadow);backdrop-filter:blur(12px);transition:background .6s,color .6s;z-index:5}
.brand{display:flex;align-items:center;gap:10px;min-width:0}
.brand svg{width:34px;height:34px;flex:none}.brand svg rect{fill:var(--wine)}.brand svg path{stroke:#f6e3b4;stroke-width:2.6;fill:none}
.brand strong{display:block;font:600 17px/1.1 var(--serif);letter-spacing:.2px}.brand span{display:block;font-size:11.5px;opacity:.7;white-space:nowrap}
.when{display:flex;flex-direction:column;line-height:1.2;min-width:150px}.date{font-weight:700;font-size:15px}.date-short{display:none;font-weight:700;font-size:13px;white-space:nowrap}.daykind{font-size:12px;opacity:.72}
.clock{display:flex;align-items:center;gap:8px}.clock strong{font:500 30px/1 var(--mono);letter-spacing:-1px}
.sun{width:22px;height:22px;border-radius:50%;background:radial-gradient(circle at 40% 40%,#ffe9a8,#f0b544 60%,#d98a20);box-shadow:0 0 14px rgba(240,181,68,.8);transition:all .6s}
body[data-sky=night] .sun{background:radial-gradient(circle at 35% 35%,#fffbe8,#d9d3c0 55%,#a59f8c);box-shadow:0 0 12px rgba(230,226,210,.55);transform:scale(.85)}
.resources{display:flex;gap:24px;margin:0 0 0 auto}
.resources div{min-width:0}.resources dt{font-size:10.5px;letter-spacing:.9px;text-transform:uppercase;opacity:.65;white-space:nowrap}
.resources dd{margin:0;font:600 19px/1.15 var(--sans);font-variant-numeric:tabular-nums;white-space:nowrap}.resources dd small{font-size:12px;font-weight:600;margin-left:4px}
.pos{color:var(--green)}.neg{color:var(--red)}body[data-sky=night] .pos{color:#8fd19e}body[data-sky=night] .neg{color:#ff9b8c}

/* raíl de navegación */
.rail{position:absolute;top:12px;bottom:12px;left:12px;width:var(--rail-w);display:flex;flex-direction:column;gap:2px;padding:10px 6px;background:#2a1f1c;border-radius:20px;box-shadow:var(--shadow);z-index:6;overflow-y:auto;scrollbar-width:none}
.rail::-webkit-scrollbar{display:none}
.rail button{display:flex;flex-direction:column;align-items:center;gap:3px;padding:8px 2px 7px;border:0;border-radius:12px;background:none;color:#d9c9ad;font-size:10.5px;font-weight:600;letter-spacing:.2px;cursor:pointer;line-height:1.15;text-align:center}
.rail button svg{width:22px;height:22px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.rail button:hover{background:rgba(255,255,255,.07);color:#fff4dc}
.rail button.active{background:var(--wine);color:#fff4dc}
.rail .spacer{flex:1;min-height:8px}
.rail .badge{position:absolute;margin:-4px 0 0 22px;min-width:16px;height:16px;padding:0 4px;border-radius:8px;background:var(--gold-2);color:#2a1f1c;font-size:10px;line-height:16px}

/* herramientas del mapa */
.map-tools{position:absolute;right:14px;top:96px;display:flex;flex-direction:column;align-items:flex-end;gap:10px;z-index:4}
.layer-switch{display:flex;padding:4px;background:var(--hud);border-radius:999px;box-shadow:var(--shadow);backdrop-filter:blur(10px)}
.layer-switch button{border:0;background:none;padding:7px 14px;border-radius:999px;color:var(--hud-ink);font-weight:600;font-size:13px;cursor:pointer}
.layer-switch button.active{background:var(--wine);color:#fff4dc}
.zoom{display:flex;flex-direction:column;background:var(--hud);border-radius:14px;box-shadow:var(--shadow);overflow:hidden}
.zoom button{width:42px;height:40px;border:0;background:none;color:var(--hud-ink);font-size:20px;cursor:pointer}.zoom button+button{border-top:1px solid var(--rule)}
.zoom button:hover,.layer-switch button:not(.active):hover{background:rgba(138,42,70,.1)}

/* misión */
.mission{position:absolute;left:calc(var(--rail-w) + 14px);top:96px;width:300px;padding:14px 16px;background:var(--hud);color:var(--hud-ink);border-radius:var(--radius);box-shadow:var(--shadow);backdrop-filter:blur(10px);z-index:3;cursor:pointer}
.mission .kicker{font-size:11px;letter-spacing:1.4px;text-transform:uppercase;color:var(--gold)}
.mission h2{margin:2px 0 8px;font:600 20px/1.15 var(--serif)}
.mission ul{list-style:none;margin:0;padding:0;display:grid;gap:5px;font-size:13px}
.mission li{display:grid;grid-template-columns:16px 1fr auto;gap:8px;align-items:center}
.mission li i{width:14px;height:14px;border-radius:50%;border:1.5px solid currentColor;opacity:.5}.mission li.done i{background:var(--green);border-color:var(--green);opacity:1}
.mission li span:last-child{font-variant-numeric:tabular-nums;opacity:.75}
.meter{height:4px;border-radius:2px;background:var(--rule);overflow:hidden;margin-top:3px}.meter span{display:block;height:100%;background:var(--gold-2)}

/* leyenda */
.legend{position:absolute;left:calc(var(--rail-w) + 14px);bottom:112px;display:flex;flex-wrap:wrap;gap:6px 14px;max-width:560px;padding:8px 14px;background:var(--hud);color:var(--hud-ink);border-radius:12px;font-size:12px;box-shadow:var(--shadow);z-index:3}
.legend span{display:inline-flex;align-items:center;gap:6px;white-space:nowrap}.legend i{display:inline-block;width:18px;height:4px;border-radius:2px}
.legend i.dash{background:repeating-linear-gradient(90deg,currentColor 0 4px,transparent 4px 7px)!important;opacity:.6}
.credit{position:absolute;right:14px;bottom:100px;font-size:10.5px;color:rgba(40,30,20,.7);z-index:2;text-align:right}.credit a{color:inherit}
body[data-sky=night] .credit{color:rgba(240,230,210,.65)}

/* barra de jornada */
.daybar{position:absolute;left:calc(var(--rail-w) + 14px);right:14px;bottom:12px;display:grid;grid-template-columns:auto 1fr auto;gap:22px;align-items:center;padding:12px 16px 12px 18px;background:var(--hud);color:var(--hud-ink);border-radius:18px;box-shadow:var(--shadow);backdrop-filter:blur(12px);z-index:5}
.turn{display:flex;flex-direction:column;line-height:1.2;min-width:170px}.turn small{font-size:11px;letter-spacing:1.2px;text-transform:uppercase;opacity:.65}.turn strong{font:600 18px/1.2 var(--serif)}.turn span{font-size:12.5px;opacity:.75}
.timeline{position:relative;height:58px;cursor:default}.timeline canvas{width:100%;height:100%;display:block}
.controls{display:flex;align-items:center;gap:6px}
.speed{display:flex;background:rgba(74,56,36,.08);border-radius:999px;padding:3px}body[data-sky=night] .speed{background:rgba(255,255,255,.08)}
.speed button{border:0;background:none;padding:6px 10px;border-radius:999px;font-weight:700;font-size:12.5px;cursor:pointer;color:inherit;font-variant-numeric:tabular-nums}
.speed button.active{background:var(--hud-ink);color:var(--hud)}
.play{width:44px;height:44px;border-radius:50%;border:0;background:var(--wine);color:#fff4dc;font-size:17px;cursor:pointer;box-shadow:0 4px 12px rgba(138,42,70,.35)}
.btn{border:0;border-radius:999px;padding:10px 18px;font-weight:700;cursor:pointer;background:rgba(74,56,36,.09);color:inherit;white-space:nowrap}
.btn:hover{background:rgba(74,56,36,.16)}
.btn.primary{background:var(--wine);color:#fff4dc}.btn.primary:hover{background:var(--wine-2)}
.btn.gold{background:var(--gold-2);color:#2a1f1c}
.btn.danger{background:none;color:var(--red);box-shadow:inset 0 0 0 1.5px currentColor}
.btn.ghost{background:none;box-shadow:inset 0 0 0 1.5px var(--rule-2)}
.btn.small{padding:6px 12px;font-size:13px}
.btn:disabled{opacity:.42;cursor:not-allowed}
body[data-sky=night] .btn:not(.primary):not(.gold){background:rgba(255,255,255,.08)}

/* cajón de páginas: una sola superficie, sin tarjetas anidadas */
.drawer{position:absolute;top:12px;bottom:12px;left:calc(var(--rail-w) + 14px);width:min(820px,calc(100vw - var(--rail-w) - 40px));background:var(--paper);color:var(--ink);border-radius:20px;box-shadow:var(--shadow);z-index:7;display:flex;flex-direction:column;overflow:hidden;animation:slide .22s ease-out}
@keyframes slide{from{transform:translateX(-14px);opacity:0}}
.drawer>header{display:flex;align-items:flex-start;gap:18px;padding:26px 32px 18px;border-bottom:1px solid var(--rule)}
.drawer>header .kicker{font-size:11.5px;letter-spacing:1.6px;text-transform:uppercase;color:var(--wine);font-weight:700}
.drawer>header h1{margin:4px 0 4px;font:600 31px/1.08 var(--serif);letter-spacing:-.3px}
.drawer>header p{margin:0;color:var(--ink-2);max-width:620px}
.drawer>header .close{margin-left:auto}
.drawer .body{flex:1;overflow-y:auto;padding:8px 32px 40px}
.close{flex:none;width:38px;height:38px;border-radius:50%;border:0;background:rgba(74,56,36,.08);font-size:20px;cursor:pointer;color:inherit}
.close:hover{background:rgba(74,56,36,.16)}
h2.section{margin:30px 0 10px;font:600 21px/1.2 var(--serif)}
h3{margin:18px 0 6px;font-size:15px}
.muted{color:var(--ink-3)}.small{font-size:13px}.note{font-size:12.5px;color:var(--ink-3);margin-top:16px;line-height:1.55}
.tabs{display:flex;gap:4px;flex-wrap:wrap;margin:16px 0 10px}
.tabs button{border:0;background:none;padding:7px 13px;border-radius:999px;font-weight:600;font-size:13.5px;cursor:pointer;color:var(--ink-2)}
.tabs button.active{background:var(--ink);color:var(--paper)}.tabs button:not(.active):hover{background:rgba(74,56,36,.08)}
.toolbar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:14px 0}
input[type=search],input[type=number],input[type=text],input[type=date],select{padding:9px 13px;border:1.5px solid var(--rule-2);border-radius:10px;background:#fffaf0;min-width:0}
input[type=search]{flex:1;min-width:200px;border-radius:999px;padding-left:16px}
input:focus-visible,select:focus-visible,button:focus-visible{outline:2.5px solid var(--gold-2);outline-offset:2px}
label{display:block;font-size:12.5px;font-weight:600;color:var(--ink-2);margin:12px 0 5px}
input[type=range]{width:100%;accent-color:var(--wine)}

/* cifras clave en fila (sin cajas) */
.figures{display:flex;flex-wrap:wrap;gap:8px 34px;margin:18px 0 6px}
.figures div{min-width:110px}.figures dt,.figures small{display:block;font-size:11px;letter-spacing:1px;text-transform:uppercase;color:var(--ink-3);font-weight:600}
.figures dd,.figures strong{display:block;margin:0;font:600 26px/1.15 var(--serif);font-variant-numeric:tabular-nums}
.figures em{font-style:normal;font-size:12.5px;color:var(--ink-3)}

/* listas y tablas planas */
table{width:100%;border-collapse:collapse;font-size:14px}
th{text-align:left;font-size:11px;letter-spacing:1px;text-transform:uppercase;color:var(--ink-3);font-weight:700;padding:10px 8px;border-bottom:1.5px solid var(--rule-2);position:sticky;top:0;background:var(--paper);z-index:1}
td{padding:10px 8px;border-bottom:1px solid var(--rule);vertical-align:middle}
td small{display:block;color:var(--ink-3);font-size:12px}
tr.clickable{cursor:pointer}tr.clickable:hover td{background:rgba(201,138,28,.08)}
.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
.chip{display:inline-flex;align-items:center;justify-content:center;min-width:34px;height:22px;padding:0 7px;border-radius:6px;color:#fff;font-weight:800;font-size:12px;letter-spacing:.2px;text-shadow:0 1px 0 rgba(0,0,0,.18)}
.status{display:inline-flex;align-items:center;gap:6px;font-size:13px;font-weight:600;white-space:nowrap}.status::before{content:'';width:8px;height:8px;border-radius:50%;background:var(--ink-3)}
.status.on::before{background:var(--green)}.status.works::before{background:var(--gold)}.status.off::before{background:transparent;box-shadow:inset 0 0 0 1.5px var(--ink-3)}.status.late::before{background:var(--red)}
.rows>div{display:grid;grid-template-columns:auto 1fr auto;gap:14px;align-items:center;padding:13px 0;border-bottom:1px solid var(--rule)}
.rows>div:last-child{border-bottom:0}
.rows h3{margin:0;font-size:15.5px}.rows p{margin:2px 0 0;color:var(--ink-2);font-size:13.5px}
.bar{position:relative;height:8px;border-radius:4px;background:var(--paper-3);overflow:hidden}.bar span{position:absolute;inset:0 auto 0 0;background:var(--wine);border-radius:4px}
.bar.gold span{background:var(--gold-2)}.bar.green span{background:var(--green)}
.split{display:flex;justify-content:space-between;gap:12px;align-items:baseline}
.group-title{display:flex;align-items:center;gap:12px;margin:26px 0 4px;padding-bottom:6px;border-bottom:1.5px solid var(--ink)}
.group-title h2{margin:0;font:600 20px/1.2 var(--serif)}.group-title span{color:var(--ink-3);font-size:13px}.group-title button{margin-left:auto}
.empty{padding:30px 0;color:var(--ink-3);text-align:center}
.callout{margin:16px 0;padding:12px 0 12px 16px;border-left:3px solid var(--gold-2);color:var(--ink-2);font-size:13.5px}
.callout.red{border-color:var(--red)}

/* panel de salidas */
.board{background:#1d1a17;color:#f4e3b9;border-radius:14px;padding:6px 0;font-family:var(--mono);font-size:13.5px;margin:14px 0}
.board .row{display:grid;grid-template-columns:62px 92px 1fr 120px;gap:12px;align-items:center;padding:7px 16px;border-bottom:1px solid rgba(255,255,255,.06)}
.board .row:last-child{border-bottom:0}.board .head{font-size:10.5px;letter-spacing:1.3px;color:#a89a7c;text-transform:uppercase}
.board .chip{font-family:var(--sans)}.board .late{color:#ff8f7a}.board .ok{color:#9fd8a8}.board .run{color:#ffd27a}
.board .dest{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-family:var(--sans);font-weight:600}
.board button{all:unset;cursor:pointer}

/* inspector lateral */
.inspector{position:absolute;right:14px;top:150px;bottom:112px;width:390px;background:var(--paper);color:var(--ink);border-radius:20px;box-shadow:var(--shadow);z-index:6;display:flex;flex-direction:column;overflow:hidden;animation:slide2 .2s ease-out}
@keyframes slide2{from{transform:translateX(14px);opacity:0}}
.inspector>header{padding:18px 20px 12px;display:flex;gap:12px;align-items:flex-start;border-bottom:1px solid var(--rule)}
.inspector>header .kicker{font-size:11px;letter-spacing:1.4px;text-transform:uppercase;color:var(--wine);font-weight:700}
.inspector>header h2{margin:2px 0 0;font:600 22px/1.15 var(--serif)}
.inspector>header .close{margin-left:auto;width:34px;height:34px}
.inspector .body{flex:1;overflow-y:auto;padding:4px 20px 22px}
.inspector .figures{gap:6px 22px}.inspector .figures dd{font-size:21px}
.hist{display:flex;align-items:flex-end;gap:2px;height:64px;margin:10px 0 2px}.hist i{flex:1;background:var(--wine);border-radius:2px 2px 0 0;opacity:.85;min-height:1px}
.hist i.now{background:var(--gold-2);opacity:1}
.axis{display:flex;justify-content:space-between;font-size:11px;color:var(--ink-3);font-family:var(--mono)}
.shares{display:flex;height:12px;border-radius:6px;overflow:hidden;margin:8px 0 6px}.shares span{display:block}
.shares-legend{display:flex;flex-wrap:wrap;gap:4px 14px;font-size:12.5px;color:var(--ink-2)}.shares-legend i{display:inline-block;width:9px;height:9px;border-radius:2px;margin-right:5px}
.stops{list-style:none;margin:12px 0 0;padding:0;position:relative}
.stops li{position:relative;display:grid;grid-template-columns:58px 1fr;gap:10px;padding:5px 0 5px 22px;font-size:13.5px}
.stops li::before{content:'';position:absolute;left:5px;top:12px;width:9px;height:9px;border-radius:50%;background:var(--paper);box-shadow:inset 0 0 0 2px var(--line-color,var(--wine))}
.stops li::after{content:'';position:absolute;left:8.5px;top:21px;bottom:-12px;width:2px;background:var(--line-color,var(--wine));opacity:.5}
.stops li:last-child::after{display:none}.stops li.past{color:var(--ink-3)}.stops li.past::before{background:var(--line-color,var(--wine))}
.stops li.here::before{background:var(--gold-2);box-shadow:0 0 0 4px rgba(240,181,68,.3)}
.stops time{font-family:var(--mono);font-size:12.5px}

/* incidencias */
.incident{padding:14px 0;border-bottom:1px solid var(--rule)}
.incident .split strong{font-size:15.5px}.incident p{margin:3px 0 10px;color:var(--ink-2);font-size:13.5px}
.incident .actions{display:flex;flex-wrap:wrap;gap:8px}

/* misión flotante de incidencias */
.alert-pill{position:absolute;left:50%;top:92px;transform:translateX(-50%);display:flex;align-items:center;gap:12px;padding:10px 14px 10px 18px;background:#2a1f1c;color:#fff1d6;border-radius:999px;box-shadow:var(--shadow);z-index:8;font-weight:600;font-size:14px;animation:pop .3s}
@keyframes pop{from{transform:translate(-50%,-10px);opacity:0}}
.alert-pill b{color:var(--gold-2)}

/* tarjetas modales */
dialog#modal{border:0;padding:0;border-radius:24px;max-width:min(880px,94vw);width:880px;max-height:92vh;background:var(--paper);color:var(--ink);box-shadow:0 40px 120px rgba(20,10,5,.5);overflow:hidden}
dialog#modal::backdrop{background:rgba(30,20,14,.55);backdrop-filter:blur(3px)}
.modal{display:grid;grid-template-columns:300px 1fr;min-height:420px;max-height:92vh}
.modal.single{grid-template-columns:1fr}
.modal .art{background-size:cover;background-position:center}
.modal .content{padding:34px 38px;overflow-y:auto;max-height:92vh}
.modal .kicker{font-size:11.5px;letter-spacing:1.6px;text-transform:uppercase;color:var(--wine);font-weight:700}
.modal h1{margin:6px 0 12px;font:600 34px/1.06 var(--serif);letter-spacing:-.4px}
.modal p{color:var(--ink-2)}
.modal .actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px}
.portrait{background-size:cover;background-position:center 18%;background-repeat:no-repeat;background-color:#3a2a22}
.hero-art{background-image:linear-gradient(180deg,rgba(42,31,28,0) 50%,rgba(42,31,28,.55)),url('data:image/jpeg;base64,');background-size:cover;background-position:62% center}
.choice{display:block;width:100%;text-align:left;margin:10px 0 0;padding:14px 18px;border:0;border-radius:14px;background:var(--paper-2);cursor:pointer}
.choice:hover:not(:disabled){background:var(--paper-3)}.choice strong{display:block;font-size:15.5px}.choice span{display:block;color:var(--ink-2);font-size:13.5px;margin-top:2px}
.choice:disabled{opacity:.5;cursor:not-allowed}
.ring{--p:0;width:118px;height:118px;border-radius:50%;background:conic-gradient(var(--green) calc(var(--p)*1%),var(--paper-3) 0);display:grid;place-items:center;flex:none}
.ring div{width:94px;height:94px;border-radius:50%;background:var(--paper);display:grid;place-items:center;text-align:center;line-height:1.05}.ring strong{font:600 28px var(--serif)}.ring small{font-size:11px;color:var(--ink-3)}
.report-head{display:flex;gap:26px;align-items:center;margin:8px 0 6px}

/* ilustraciones de tren */
.train-art{display:block;width:100%;max-width:360px;height:auto}
.catalogue>div{display:grid;grid-template-columns:220px 1fr auto;gap:20px;align-items:center;padding:16px 0;border-bottom:1px solid var(--rule)}
.catalogue h3{margin:0;font:600 18px/1.2 var(--serif)}.catalogue p{margin:3px 0;color:var(--ink-2);font-size:13.5px}
.specline{display:flex;flex-wrap:wrap;gap:4px 14px;font-size:12.5px;color:var(--ink-3)}.specline b{color:var(--ink);font-weight:700}
.chapters{display:grid;grid-template-columns:repeat(5,1fr);gap:0;margin:18px 0;border-top:3px solid var(--paper-3)}
.chapters div{padding:10px 10px 0 0;position:relative;font-size:12.5px;color:var(--ink-3)}
.chapters div::before{content:'';position:absolute;top:-8px;left:0;width:13px;height:13px;border-radius:50%;background:var(--paper-3)}
.chapters div.done::before{background:var(--green)}.chapters div.now::before{background:var(--gold-2);box-shadow:0 0 0 4px rgba(240,181,68,.3)}
.chapters strong{display:block;color:var(--ink);font-size:13.5px}
.story{display:grid;grid-template-columns:190px 1fr;gap:24px;margin-top:10px}.story .portrait{border-radius:16px;min-height:240px}
.objectives{list-style:none;padding:0;margin:14px 0}.objectives li{display:grid;grid-template-columns:22px 1fr auto;gap:10px;align-items:center;padding:9px 0;border-bottom:1px solid var(--rule)}
.objectives li i{width:18px;height:18px;border-radius:50%;box-shadow:inset 0 0 0 2px var(--ink-3)}.objectives li.done i{background:var(--green);box-shadow:none}
.chart{width:100%;height:190px;display:block}
.news{display:grid;grid-template-columns:120px 1fr;gap:16px;padding:12px 0;border-bottom:1px solid var(--rule)}.news time{font-size:12.5px;color:var(--ink-3);text-transform:capitalize}.news h3{margin:0}.news p{margin:3px 0 0;color:var(--ink-2)}
.method li{margin:8px 0;color:var(--ink-2)}
kbd{font-family:var(--mono);font-size:12px;padding:1px 6px;border-radius:5px;background:var(--paper-3)}

#toast{position:fixed;left:50%;bottom:110px;transform:translate(-50%,20px);padding:11px 20px;background:#2a1f1c;color:#fff1d6;border-radius:999px;font-weight:600;opacity:0;pointer-events:none;transition:all .25s;z-index:30;max-width:90vw;text-align:center}
#toast.show{opacity:1;transform:translate(-50%,0)}

/* tamaños intermedios */
@media (max-width:1280px){.brand div{display:none}.resources{gap:16px}.resources dd{font-size:16px}.mission{width:260px}}
@media (max-width:1050px){.resources div:nth-child(n+4){display:none}.legend{display:none}.inspector{width:350px}}
/* móvil */
@media (max-width:760px){
 :root{--rail-w:0px}
 .hud{left:8px;right:8px;top:8px;gap:12px;padding:8px 12px;border-radius:14px}.brand,.resources div:nth-child(n+2),.date,.daykind{display:none}.date-short{display:block}.when{min-width:0}.clock strong{font-size:22px}.resources{gap:12px}.resources dd{font-size:14px}
 .rail{top:auto;bottom:0;left:0;right:0;width:auto;height:62px;flex-direction:row;border-radius:0;padding:4px 6px calc(4px + env(safe-area-inset-bottom));overflow-x:auto;overflow-y:hidden;gap:0}
 .rail button{min-width:64px;font-size:10px}.rail .spacer{display:none}
 .daybar{left:8px;right:8px;bottom:70px;grid-template-columns:minmax(0,1fr);gap:8px;padding:8px 10px}.turn{display:none}.timeline{height:40px}.controls{flex-wrap:wrap;gap:6px}.speed button{padding:5px 7px}.play{width:38px;height:38px}.controls .btn{padding:8px 12px;font-size:13px}
 .mission{display:none}.map-tools{top:auto;bottom:176px;right:8px}.layer-switch button{padding:6px 10px;font-size:12px}
 .drawer{left:0;right:0;top:0;bottom:62px;width:auto;border-radius:0}.drawer>header{padding:18px 18px 12px}.drawer>header h1{font-size:24px}.drawer .body{padding:6px 18px 30px}
 .inspector{left:0;right:0;top:auto;bottom:62px;width:auto;max-height:62vh;border-radius:20px 20px 0 0}
 .credit{display:none}.modal{grid-template-columns:1fr}.modal .art{height:180px}.modal .content{padding:24px 22px}.modal h1{font-size:27px}
 .catalogue>div{grid-template-columns:1fr}.story{grid-template-columns:1fr}.board .row{grid-template-columns:52px 70px 1fr;}.board .row>:nth-child(4){display:none}
 .chapters{grid-template-columns:repeat(5,minmax(70px,1fr));overflow-x:auto}
 #toast{bottom:186px}
}

/* ---- v0.4: menú visual de ciudad ---- */
.inspector.wide{width:440px;top:96px}
.close.floating{position:absolute;right:12px;top:12px;z-index:2;background:rgba(255,250,240,.85);backdrop-filter:blur(6px)}
.inspector .city-body{padding:0 0 24px}
.city-hero{position:relative}
.city-art{display:block;width:100%;height:auto;aspect-ratio:44/17}
.city-title{position:absolute;left:18px;bottom:16px;color:#fff;text-shadow:0 2px 10px rgba(0,0,0,.55)}
.city-title h2{margin:2px 0 0;font:600 34px/1 var(--serif)}.city-title span{display:block;font-size:12px;letter-spacing:1.2px;text-transform:uppercase;font-weight:700}
.city-stats{display:grid;grid-template-columns:repeat(3,1fr);padding:12px 18px;border-bottom:1px solid var(--rule)}
.city-stats div{display:flex;flex-direction:column}.city-stats b{font:600 22px/1.1 var(--serif);font-variant-numeric:tabular-nums}.city-stats span{font-size:11.5px;color:var(--ink-3);text-transform:uppercase;letter-spacing:.8px}
.city-body>h3.sub{margin:18px 18px 8px;font:600 18px var(--serif)}
.city-body>p,.city-body>.btn{margin-left:18px;margin-right:18px}
.city-body .board{margin:8px 18px}
.req{position:relative;margin:12px 18px 0;padding:12px 14px;border-radius:14px;background:#fff5e0;border-left:4px solid var(--gold-2);display:flex;flex-direction:column;gap:3px}
.req b{font-size:14.5px;padding-right:74px}.req span{font-size:13px;color:var(--ink-2)}.req em{position:absolute;right:14px;top:12px;font-style:normal;font-weight:800;color:var(--green)}
.req.red{background:#fde9e4;border-color:var(--red)}.req.gold{background:#fff0c9;border-color:#e09a1a}
.req .actions{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}
.conns{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:0 18px}
.conn{border-radius:14px;padding:11px 12px;background:#fffaf0;box-shadow:0 1px 0 var(--rule-2),0 4px 14px rgba(60,40,20,.06);display:flex;flex-direction:column;gap:7px;transition:transform .15s}
.conn:hover{transform:translateY(-2px)}
.conn.off{background:#f1ebde}.conn.locked{background:#ece6d8;opacity:.75}.conn.hot{box-shadow:0 0 0 2.5px var(--gold-2),0 6px 18px rgba(240,181,68,.35)}
.conn-top{display:flex;align-items:center;gap:7px;min-width:0}.conn-top strong{font-size:14.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.conn-top .chip{min-width:0;font-size:11px;height:20px;padding:0 6px}
.flag{margin-left:auto;font-size:10.5px;font-weight:800;color:#8a5a00;background:#ffe2a0;padding:2px 7px;border-radius:999px;white-space:nowrap}
.conn-bar{height:7px;border-radius:4px;background:var(--paper-3);overflow:hidden}.conn-bar span{display:block;height:100%;border-radius:4px;transition:width .3s}
.conn-meta{font-size:12px;color:var(--ink-2);line-height:1.35;min-height:32px}
.conn-actions{display:flex;align-items:center;gap:6px}.conn-actions .ghost{margin-left:auto;padding:5px 9px;font-size:12px}
.round{width:34px;height:34px;border-radius:50%;border:0;background:var(--paper-3);font-size:20px;font-weight:800;cursor:pointer;line-height:1;color:var(--ink)}
.round.plus{background:var(--wine);color:#fff4dc}.round:hover:not(:disabled){filter:brightness(1.08)}.round:disabled{opacity:.35;cursor:not-allowed}
.stations{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;padding:0 18px 10px}
.stations div{display:flex;flex-direction:column;align-items:center;gap:3px;font-size:10.5px;text-align:center;color:var(--ink-3)}
.stations div.have{color:var(--ink)}
.st-icon{width:44px;height:34px;fill:#d8cdb6;stroke:#8a7c69;stroke-width:1.2}.stations .have .st-icon{fill:#f0c46a;stroke:#7a4b12}.st-icon.on{filter:drop-shadow(0 0 6px rgba(240,181,68,.8))}
.mission .requests{margin-top:12px;padding-top:10px;border-top:1px solid var(--rule);display:flex;flex-direction:column;gap:6px;max-height:260px;overflow-y:auto}
.mission .requests button{all:unset;cursor:pointer;display:grid;grid-template-columns:1fr auto;gap:0 8px;padding:7px 9px;border-radius:10px;background:rgba(240,181,68,.14)}
.mission .requests button:hover{background:rgba(240,181,68,.28)}
.mission .requests b{font-size:13px}.mission .requests span{grid-column:1;font-size:12px;opacity:.8}.mission .requests em{grid-row:1/3;grid-column:2;align-self:center;font-style:normal;font-weight:800;color:var(--green);font-size:12.5px}
body[data-sky=night] .mission .requests em{color:#8fd19e}
.legend i.dot{width:11px;height:11px;border-radius:50%;border:3px solid;background:transparent}
.legend i.pin{width:16px;height:16px;border-radius:50%;background:#c23b2f;color:#fff;font-style:normal;font-weight:800;font-size:11px;display:grid;place-items:center}
.alert-pill.gold{background:#7a4b12}
/* tutorial */
.spot{position:fixed;z-index:40;pointer-events:none;box-shadow:0 0 0 9999px rgba(20,12,8,.45),0 0 0 3px #f0b544,0 0 24px 6px rgba(240,181,68,.7);transition:all .25s;animation:spotpulse 1.6s infinite}
@keyframes spotpulse{50%{box-shadow:0 0 0 9999px rgba(20,12,8,.45),0 0 0 5px #f0b544,0 0 34px 10px rgba(240,181,68,.8)}}
dialog .spot,dialog .coach{position:absolute}
.coach{position:fixed;z-index:41;width:380px;max-width:calc(100vw - 24px);display:grid;grid-template-columns:64px 1fr;gap:12px;padding:14px 16px;background:var(--paper);color:var(--ink);border-radius:18px;box-shadow:0 20px 60px rgba(20,10,5,.45);transition:left .25s,top .25s}
.coach .portrait{width:64px;height:64px;border-radius:50%;background-size:300% 160%;background-position:50% 18%}
.coach .kicker{font-size:10.5px;letter-spacing:1.3px;text-transform:uppercase;color:var(--wine);font-weight:800}
.coach h3{margin:2px 0 4px;font:600 18px var(--serif)}.coach p{margin:0;font-size:13.5px;color:var(--ink-2)}
.coach .actions{display:flex;gap:6px;margin-top:10px}
@media (max-width:760px){.inspector.wide{width:auto;top:auto}.conns{grid-template-columns:1fr}.coach{grid-template-columns:44px 1fr}.coach .portrait{width:44px;height:44px}}

.legend i.crowd{font-style:normal;color:#c23b2f;font-size:9px;letter-spacing:-1px;width:auto;height:auto;background:none}

.alert-pill{max-width:calc(100vw - 24px)}
@media (max-width:760px){.alert-pill{top:70px;width:calc(100vw - 16px);border-radius:16px;font-size:13px;padding:8px 10px}.alert-pill span:nth-child(2){flex:1}}

/* fotografías del material en el taller */
.train-photo{display:block;width:100%;max-width:300px;height:auto;border-radius:10px;aspect-ratio:3/2;object-fit:contain;background:#e9eceb}
.train3d{border-radius:14px;overflow:hidden;margin:10px 0;background:#e9eceb;min-height:120px}
.train-workshop-photo{margin:0}.train-workshop-photo .train-photo{max-width:none;border-radius:0}
.train-workshop-photo figcaption{display:flex;justify-content:space-between;gap:12px;padding:9px 12px;background:var(--paper);font-size:11px;color:var(--ink-3)}
.train-workshop-photo figcaption span{flex:none;font-size:10px;opacity:.8}
.train-photo-pending{display:grid;place-items:center;min-height:110px;background:#edf1ef;color:#64726e;font:12px var(--sans)}

/* banda sonora */
.rail .music-btn.on svg{color:var(--gold-2);animation:beat 1.1s infinite}
@keyframes beat{50%{transform:scale(1.25)}}
.tracks h3{margin:16px 0 6px;font:600 16px var(--serif)}
.track{display:grid;grid-template-columns:34px 1fr 40px;gap:10px;align-items:center;width:100%;text-align:left;border:0;background:none;padding:9px 10px;border-radius:12px;cursor:pointer;color:inherit}
.track:hover{background:var(--paper-2)}.track.on{background:#f6e4c0}.track .no{font-family:var(--mono);color:var(--ink-3)}.track b{display:block;font-size:15px}.track em{font-style:normal;font-size:12.5px;color:var(--ink-3)}
.track .eq{display:flex;gap:2px;align-items:flex-end;height:16px;justify-content:center;color:var(--wine)}.track .eq i{width:3px;background:var(--wine);animation:eq .8s infinite ease-in-out}.track .eq i:nth-child(2){animation-delay:.2s}.track .eq i:nth-child(3){animation-delay:.4s}
@keyframes eq{0%,100%{height:4px}50%{height:16px}}

/* voces de los personajes */
.say-btn{display:inline-grid;place-items:center;width:30px;height:30px;margin-left:6px;vertical-align:middle;border:0;border-radius:50%;background:var(--paper-2,#efe4cf);color:var(--wine);font-size:14px;cursor:pointer;line-height:1}
.say-btn:hover{background:#f6e4c0}
.say-s{transition:background .25s,color .25s;border-radius:4px}
.say-s.on{background:rgba(214,160,60,.28);color:inherit;box-shadow:0 0 0 2px rgba(214,160,60,.28)}
.dialogue-opener{display:block;margin:0 0 .6em;font-weight:650;color:var(--wine)}
.dialogue-main{display:block}
.portrait.talking{animation:talk .32s ease-in-out infinite alternate}
@keyframes talk{from{transform:translateY(0) rotate(-.6deg)}to{transform:translateY(-2px) rotate(.6deg) scale(1.015)}}
.speaker{display:flex;align-items:center;gap:6px}.speaker .say-btn{margin-left:0}
@media (prefers-reduced-motion:reduce){.portrait.talking{animation:none}}


/* ================================================================ 2.0 · papel, esmalte y vía
   Paneles de papel con doble filete dorado, cabeceras como placas de esmalte de estación,
   pestañas de billete y una vía con traviesas como separador. */
:root{--paper:#f6eedc;--paper-2:#ede1c7;--paper-3:#e2d3b1;--ink:#2a211b;--ink-2:#5b4e40;--ink-3:#8b7b66;--frame:#c4a05a;--frame-2:rgba(196,160,90,.45);
 --enamel:#231b17;--enamel-2:#2e241e;--cream:#f6e7c4;--hud:rgba(35,27,23,.94);--hud-ink:#f3e4c2;--radius:10px;
 --rails:linear-gradient(var(--frame),var(--frame)) top/100% 1.5px no-repeat,linear-gradient(var(--frame),var(--frame)) bottom/100% 1.5px no-repeat,repeating-linear-gradient(90deg,#7d5f33 0 3px,transparent 3px 11px)}
body[data-sky=night]{--hud:rgba(22,19,24,.94);--hud-ink:#f3e4c2}
.paperish,.drawer,.inspector,dialog#modal,.coach,.mission{background-color:var(--paper);background-image:radial-gradient(rgba(120,88,40,.055) 1px,transparent 1.2px),radial-gradient(rgba(255,255,255,.55) 1px,transparent 1.2px);background-size:23px 23px,37px 37px;background-position:0 0,11px 7px}
.drawer,.inspector,dialog#modal,.coach{box-shadow:var(--shadow),inset 0 0 0 1px var(--frame-2),inset 0 0 0 5px var(--paper),inset 0 0 0 6px var(--frame-2)}
.ic{width:1.15em;height:1.15em;vertical-align:-.2em;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:none}

/* barra superior y de jornada: esmalte oscuro */
.hud,.daybar{background:var(--hud);color:var(--hud-ink);border-radius:12px;box-shadow:var(--shadow),inset 0 0 0 1px rgba(196,160,90,.35)}
.hud .brand strong{font:600 18px/1.1 var(--serif);letter-spacing:.3px}.hud .brand span{color:var(--frame);opacity:1;letter-spacing:.6px}
.brand svg rect{fill:var(--wine)}
.resources dt{color:var(--frame);opacity:1;letter-spacing:1.1px}
.hud .pos{color:#9fd6a6}.hud .neg{color:#ff9e8c}
.daybar .turn small{color:var(--frame);opacity:1}.daybar .turn strong{color:var(--cream)}
.speed{background:rgba(255,255,255,.07)!important}.speed button.active{background:var(--cream);color:var(--enamel)}
.play{border-radius:10px;background:linear-gradient(#9b3253,#7c213f);box-shadow:inset 0 0 0 1px rgba(255,236,200,.28),0 2px 0 #50142a}
.daybar .btn:not(.primary){background:rgba(255,255,255,.07);color:var(--cream);box-shadow:inset 0 0 0 1px rgba(196,160,90,.4)}

/* raíl de navegación: placas de latón */
.rail{background:linear-gradient(#2a211c,#1f1814);border-radius:14px;box-shadow:var(--shadow),inset 0 0 0 1px rgba(196,160,90,.32);gap:6px;padding:12px 7px}
.rail button{border-radius:8px;color:#d6c4a2;font-size:10.5px;letter-spacing:.5px;text-transform:uppercase;padding:10px 2px 8px}
.rail button svg{stroke-width:1.5}
.rail button.active{background:linear-gradient(#f3e3bd,#e3cd99);color:#3a2418;box-shadow:inset 0 0 0 1px rgba(90,60,20,.35),0 2px 0 rgba(0,0,0,.35)}
.rail button.active svg{color:#7c213f}
.rail .spacer{border-bottom:1px solid rgba(196,160,90,.25);margin:0 8px 6px}

/* capas del mapa */
.layer-switch,.zoom{background:var(--hud);box-shadow:var(--shadow),inset 0 0 0 1px rgba(196,160,90,.35);border-radius:10px}
.layer-switch{padding:3px}.layer-switch button{color:var(--hud-ink);border-radius:7px;font-size:12.5px;letter-spacing:.3px}
.layer-switch button.active{background:var(--cream);color:var(--enamel)}.zoom button{color:var(--hud-ink)}.zoom button+button{border-top-color:rgba(196,160,90,.25)}
.layer-switch button:not(.active):hover,.zoom button:hover{background:rgba(255,255,255,.08)}

/* misión: billete con matriz */
.mission{color:var(--ink);border-radius:10px;padding:16px 18px 14px 22px;box-shadow:var(--shadow),inset 0 0 0 1px var(--frame-2)}
.mission::before{content:'';position:absolute;left:8px;top:12px;bottom:12px;border-left:2px dotted rgba(139,123,102,.55)}
.mission .kicker{color:var(--wine);font-weight:700}.mission h2{color:var(--ink)}
.mission .requests{border-top:1px dashed var(--rule-2)}
.mission .requests button{background:rgba(196,160,90,.14);border-radius:8px}.mission .requests em{color:var(--green)}

/* leyenda: tarjeta pequeña */
.legend{background:var(--paper);color:var(--ink);border-radius:9px;box-shadow:var(--shadow),inset 0 0 0 1px var(--frame-2);padding:9px 14px 9px 14px}
.legend i.rombo{width:11px;height:11px;transform:rotate(45deg);border:1.5px solid var(--ink);background:linear-gradient(90deg,#a3123a 50%,#d08a1c 50%);border-radius:1px}
.credit{color:rgba(40,30,20,.75)}

/* cajón: cabecera de esmalte con vía */
.drawer{border-radius:12px}
.drawer>header{position:relative;background:linear-gradient(#2c231d,#221a16);color:var(--cream);border-bottom:0;padding:24px 32px 22px;margin:6px 6px 0;border-radius:7px 7px 0 0}
.drawer>header::after{content:'';position:absolute;left:0;right:0;bottom:-7px;height:7px;background:var(--rails)}
.drawer>header .kicker{color:var(--frame);letter-spacing:2.2px}
.drawer>header h1{color:var(--cream);font-weight:600}
.drawer>header p{color:#cdbb98}
.drawer>header .close,.inspector>header .close{background:rgba(255,255,255,.1);color:var(--cream)}
.drawer>header .close:hover,.inspector>header .close:hover{background:rgba(255,255,255,.2)}
.drawer .body{padding:18px 34px 40px}
h2.section{display:flex;align-items:center;gap:12px;margin:30px 0 12px;font:600 21px/1.2 var(--serif)}
h2.section::after{content:'';flex:1;height:7px;background:var(--rails);opacity:.55;margin-top:2px}

/* pestañas de billete y selector */
.tabs{gap:0;margin:16px 0 14px;border-bottom:1.5px solid var(--rule-2)}
.tabs button{position:relative;border-radius:0;padding:10px 15px 10px;font-size:12px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;color:var(--ink-3)}
.tabs button:not(.active):hover{background:none;color:var(--ink)}
.tabs button.active{background:none;color:var(--wine)}
.tabs button.active::after{content:'';position:absolute;left:12px;right:12px;bottom:-2px;height:3px;background:var(--wine);border-radius:2px}
.tabs button.active::before{content:'';position:absolute;left:50%;bottom:-6px;width:7px;height:7px;background:var(--wine);transform:translateX(-50%) rotate(45deg)}
.segmented{display:inline-flex;padding:3px;margin:2px 0 4px;border-radius:9px;background:var(--paper-2);box-shadow:inset 0 0 0 1px var(--frame-2)}
.segmented button{border:0;background:none;padding:7px 18px;border-radius:7px;font-weight:700;font-size:13px;color:var(--ink-2);cursor:pointer}
.segmented button.active{background:var(--enamel);color:var(--cream);box-shadow:0 1px 0 rgba(0,0,0,.3)}

/* botones con filete */
.btn{border-radius:9px;padding:9px 16px;letter-spacing:.2px;background:var(--paper-2);box-shadow:inset 0 0 0 1px var(--frame-2)}
.btn:hover{background:var(--paper-3)}
.btn.primary{background:linear-gradient(#9b3253,#7c213f);color:#fff3dc;box-shadow:inset 0 0 0 1px rgba(255,236,200,.25),0 2px 0 #50142a}
.btn.primary:hover{background:linear-gradient(#a83a5c,#86284a)}
.btn.ghost{background:transparent;box-shadow:inset 0 0 0 1px var(--rule-2)}
.btn.danger{box-shadow:inset 0 0 0 1.5px currentColor}
.btn.small{padding:6px 11px;font-size:12.5px;border-radius:8px}
body[data-sky=night] .btn:not(.primary):not(.gold){background:var(--paper-2)}
.round{border-radius:9px;background:var(--paper-2);box-shadow:inset 0 0 0 1px var(--frame-2)}.round.plus{background:linear-gradient(#9b3253,#7c213f);box-shadow:inset 0 0 0 1px rgba(255,236,200,.25)}
.close{border-radius:9px}
.linkish{all:unset;cursor:pointer;color:var(--wine);text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:3px;text-decoration-color:rgba(124,33,63,.4)}
.linkish:hover{text-decoration-color:currentColor}

/* chapas de esmalte */
