@media(max-width:350px){.trenespop{padding-left:12px;padding-right:12px}.tp-categories{margin-left:-12px;margin-right:-12px;padding-left:12px;padding-right:12px}.tp-results h2{font-size:18px}.tp-price{font-size:18px}.tp-card-body{padding:8px 0}.tp-card-bottom{gap:2px}.tp-card-bottom .brand-logo{width:52px;height:19px}}

/* Rescate de Tenfe — HUD de juego: vidrio oscuro sobre el mapa, iconos y números, el mínimo texto. */
.rs{position:fixed;inset:0;z-index:20;font:14px/1.4 var(--sans);color:#f4ecdc;
 --g:rgba(21,18,25,.86);--g2:rgba(255,255,255,.06);--g3:rgba(255,255,255,.11);--t:#f4ecdc;--t2:#c8bca6;--t3:#8f846f;
 --gold:#f2b84b;--wine:#c4466d;--good:#74cc93;--bad:#ff8270;--blue:#7cb6e8;--r:16px;--top:72px}
.rs[hidden]{display:none}
.rs canvas.rs-map{position:absolute;inset:0;width:100%;height:100%;touch-action:none;background:#6f9fa8}
:where(.rs) button{cursor:pointer;border:0;background:none;font:inherit;color:inherit;padding:0}
.rs .num{font-family:var(--mono);font-variant-numeric:tabular-nums}
.rs-glass{background:var(--g);backdrop-filter:blur(16px) saturate(1.2);-webkit-backdrop-filter:blur(16px);border-radius:var(--r);box-shadow:0 12px 32px rgba(0,0,0,.32),inset 0 1px 0 rgba(255,255,255,.06)}
.rs svg.i{width:18px;height:18px;flex:none;stroke:currentColor;fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.pos{color:var(--good)!important}.neg{color:var(--bad)!important}

/* barra superior */
.rs-top{position:absolute;top:10px;left:10px;right:10px;height:52px;display:flex;align-items:center;gap:18px;padding:0 10px 0 16px;z-index:6}
.rs-brand{display:flex;align-items:center;gap:12px;min-width:0}
.rs-brand .logo{width:66px;height:22px;display:inline-flex;align-items:center}
.rs-week{display:flex;align-items:baseline;gap:8px;white-space:nowrap}
.rs-week b{font:800 15px/1 var(--sans)}.rs-week span{font-size:12px;color:var(--t3)}
.rs-res{display:flex;align-items:center;gap:4px;margin-left:auto}
.rs-res button{display:flex;align-items:center;gap:7px;height:38px;padding:0 12px;border-radius:12px;white-space:nowrap}
.rs-res button:hover{background:var(--g2)}
.rs-res svg.i{color:var(--gold)}
.rs-res b{font:800 16px/1 var(--sans);font-variant-numeric:tabular-nums}
.rs-res small{font-size:11.5px;font-weight:700;color:var(--t3)}
.rs-res .warn b{color:var(--gold)}.rs-res .bad b{color:var(--bad)}
.rs-orders{display:flex;gap:5px;padding:0 6px}
.rs-orders i{width:10px;height:10px;border-radius:50%;background:var(--gold);box-shadow:0 0 8px rgba(242,184,75,.6)}
.rs-orders i.used{background:transparent;box-shadow:inset 0 0 0 2px var(--g3)}
.rs-iconbtn{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;flex:none}
.rs-iconbtn:hover{background:var(--g2)}

/* raíl */
.rs-rail{position:absolute;top:var(--top);left:10px;display:flex;flex-direction:column;gap:2px;padding:6px;z-index:5}
.rs-rail button{position:relative;width:44px;height:44px;border-radius:12px;display:grid;place-items:center;color:var(--t2)}
.rs-rail button svg.i{width:21px;height:21px}
.rs-rail button:hover,.rs-rail button.on{background:var(--g3);color:var(--gold)}
.rs-rail button::after{content:attr(data-tip);position:absolute;left:52px;top:50%;transform:translateY(-50%);padding:5px 9px;border-radius:8px;background:#000c;color:#fff;font-size:12px;font-weight:700;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .15s}
.rs-rail button:hover::after{opacity:1}
.rs-rail .badge{position:absolute;top:5px;right:5px;width:8px;height:8px;border-radius:50%;background:var(--bad);box-shadow:0 0 0 2px #1a161d}

/* misión */
.rs-mission{position:absolute;top:var(--top);left:72px;width:300px;max-height:calc(100% - var(--top) - 90px);overflow:auto;padding:16px;z-index:5;scrollbar-width:none}
.rs-kick{display:flex;align-items:center;justify-content:space-between;gap:8px;font:800 10.5px/1 var(--sans);letter-spacing:1.3px;text-transform:uppercase;color:var(--gold)}
.rs-pill{padding:4px 8px;border-radius:999px;background:var(--g3);color:var(--t);font:800 11px/1 var(--sans);letter-spacing:0;text-transform:none;white-space:nowrap}
.rs-pill.hot{background:var(--wine);color:#fff}
.rs-mission h2{font:700 21px/1.15 var(--serif);margin:8px 0 12px}
.rs-goal{display:grid;gap:10px;margin-bottom:12px}
.rs-goal .row{display:grid;grid-template-columns:1fr auto;gap:5px 8px;align-items:baseline;font-size:12.5px;color:var(--t2)}
.rs-goal .row b{font:800 15px/1 var(--sans);color:var(--t)}.rs-goal .row b small{font-size:11px;color:var(--t3);font-weight:700}
.rs-goal .bar{grid-column:1/-1;height:5px;border-radius:3px;background:var(--g3);overflow:hidden}
.rs-goal .bar i{display:block;height:100%;border-radius:3px;background:linear-gradient(90deg,var(--wine),var(--gold));transition:width .6s}
.rs-goal .row.ok b{color:var(--good)}.rs-goal .row.ok .bar i{background:var(--good)}
.rs-list{display:grid;gap:2px;margin:0;padding:0;list-style:none}
.rs-list button{width:100%;display:flex;align-items:center;gap:10px;padding:8px;border-radius:10px;text-align:left;font-size:13px;color:var(--t)}
.rs-list button:hover{background:var(--g2)}
.rs-dot{width:8px;height:8px;border-radius:50%;flex:none;background:var(--gold)}.rs-dot.s3{background:var(--bad)}.rs-dot.s1{background:var(--t3)}
.rs-list .go{margin-left:auto;color:var(--t3);font-size:16px}
.rs-sep{height:1px;background:var(--g3);margin:10px 0}
.rs-cta{width:100%;display:flex;align-items:center;justify-content:center;gap:8px;height:40px;border-radius:12px;background:var(--gold);color:#241a10;font-weight:800;margin-bottom:10px}
.rs-cta:hover{filter:brightness(1.08)}
.rs-offer{width:100%;display:flex;align-items:center;gap:10px;padding:8px;border-radius:12px;text-align:left}
.rs-offer:hover{background:var(--g2)}
.rs-offer img{width:38px;height:38px;border-radius:50%;object-fit:cover;object-position:50% 20%;flex:none;box-shadow:0 0 0 2px var(--wine)}
.rs-offer b{display:block;font-size:13px}.rs-offer span{font-size:11.5px;color:var(--t3)}

/* ficha del corredor */
.rs-side{position:absolute;top:var(--top);right:10px;width:330px;max-height:calc(100% - var(--top) - 90px);overflow:auto;padding:16px;z-index:5;scrollbar-width:none;animation:rs-slide .25s ease}
@keyframes rs-slide{from{opacity:0;transform:translateX(16px)}}
.rs-side h2{font:700 22px/1.1 var(--serif);margin:6px 0 2px}
.rs-side .sub{font-size:12px;color:var(--t3)}
.rs-x{position:absolute;top:10px;right:10px;width:30px;height:30px;border-radius:50%;display:grid;place-items:center;color:var(--t2);font-size:18px;z-index:3}
.rs-x:hover{background:var(--g3);color:#fff}
.rs-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:14px 0 10px}
.rs-stat b{display:block;font:800 24px/1 var(--sans);font-variant-numeric:tabular-nums}
.rs-stat span{display:block;font-size:11px;color:var(--t3);margin-top:4px}
.rs-meta{display:flex;gap:12px;flex-wrap:wrap;font-size:12px;color:var(--t2);margin-bottom:10px}
.rs-meta b{color:var(--t)}
.rs-tags{display:flex;gap:5px;flex-wrap:wrap;margin-bottom:12px}
.rs-tag{padding:4px 8px;border-radius:999px;background:var(--g2);font-size:11.5px;color:var(--t2);white-space:nowrap}
.rs-tag b{color:var(--bad)}.rs-tag.up b{color:var(--good)}
.rs-acts{display:grid;gap:4px}
.rs-act{display:flex;align-items:center;gap:10px;width:100%;padding:10px 10px;border-radius:12px;background:var(--g2);text-align:left;font-weight:700;font-size:13.5px}
.rs-act:hover{background:var(--g3)}
.rs-act svg.i{color:var(--gold)}
.rs-act .p{margin-left:auto;font:700 12px var(--mono);color:var(--t2)}
.rs-act.main{background:var(--gold);color:#241a10}.rs-act.main svg.i{color:#241a10}.rs-act.main .p{color:#3b2a14}
.rs-act[disabled]{opacity:.38;cursor:not-allowed}
.rs-progress{display:flex;gap:3px;margin:8px 0 4px}
.rs-progress i{flex:1;height:6px;border-radius:3px;background:var(--g3)}.rs-progress i.done{background:var(--good)}.rs-progress i.on{background:var(--gold)}
.rs-workline{display:flex;justify-content:space-between;font-size:12px;color:var(--t2);margin-bottom:8px}

/* barra inferior */
.rs-dock{position:absolute;left:10px;right:10px;bottom:10px;height:58px;display:flex;align-items:center;gap:12px;padding:0 8px;z-index:6}
.rs-layers{display:flex;gap:2px}
.rs-layers button{display:flex;align-items:center;gap:6px;height:40px;padding:0 11px;border-radius:11px;font-weight:700;font-size:12.5px;color:var(--t3);white-space:nowrap}
.rs-layers button:hover{color:var(--t)}
.rs-layers button.on{background:var(--g3);color:var(--t)}
.rs-layers button i{width:9px;height:9px;border-radius:50%}
.rs-ticker{flex:1;min-width:0;display:flex;align-items:center;gap:10px;font:600 13px/1.2 var(--serif);color:var(--t2);overflow:hidden;white-space:nowrap}
.rs-ticker b{font:800 10px/1 var(--sans);letter-spacing:1.2px;color:var(--gold);flex:none}
.rs-ticker span{overflow:hidden;text-overflow:ellipsis}
.rs-go{display:flex;gap:6px;align-items:center;margin-left:auto}
.rs-next{height:44px;padding:0 22px;border-radius:14px;background:var(--gold);color:#241a10;font:800 15px/1 var(--sans);display:flex;align-items:center;gap:10px;box-shadow:0 6px 18px rgba(242,184,75,.35)}
.rs-next:hover{filter:brightness(1.08)}
.rs-next.alert{background:var(--wine);color:#fff;box-shadow:0 6px 18px rgba(196,70,109,.4)}
.rs-next[disabled]{opacity:.5}
.rs-skip{height:44px;width:44px;border-radius:14px;background:var(--g3);display:grid;place-items:center}
.rs-skip:hover{background:rgba(255,255,255,.18)}
.rs-skip[disabled]{opacity:.35}

/* ventanas */
.rs-sheet,.rs-modal{border:0;padding:0;background:transparent;max-width:none;max-height:none;color:var(--t)}
.rs-sheet::backdrop,.rs-modal::backdrop{background:rgba(8,6,10,.55);backdrop-filter:blur(3px)}
.rs-sheet>.inner,.rs-modal>.inner{background:rgba(24,21,28,.97);border-radius:20px;box-shadow:0 30px 80px rgba(0,0,0,.5);position:relative;overflow:auto;max-height:calc(100vh - 32px)}
.rs-sheet>.inner{width:min(1080px,calc(100vw - 24px));padding:26px 28px 28px}
.rs-modal>.inner{width:min(720px,calc(100vw - 24px));padding:0}
.rs-modal .body{padding:22px 24px 24px}
.rs h1{font:700 28px/1.1 var(--serif);margin:6px 0 4px}
.rs h3{font:800 15px/1.2 var(--sans);margin:0}
.rs-h{font:800 10.5px/1 var(--sans);letter-spacing:1.3px;text-transform:uppercase;color:var(--t3);margin:22px 0 10px}
.rs-lead{color:var(--t2);font-size:13.5px;margin:0 0 6px}
.rs-banner{display:block;width:100%;aspect-ratio:16/6;object-fit:cover;border-radius:20px 20px 0 0;-webkit-mask-image:linear-gradient(#000 70%,transparent);mask-image:linear-gradient(#000 70%,transparent)}
.rs-tabs{display:flex;gap:4px;margin:14px 0 16px;overflow-x:auto;scrollbar-width:none}
.rs-tabs button{padding:8px 14px;border-radius:999px;font-weight:700;font-size:13px;color:var(--t3);white-space:nowrap}
.rs-tabs button.on{background:var(--g3);color:var(--t)}
.rs-grid{display:grid;gap:10px;grid-template-columns:repeat(auto-fill,minmax(220px,1fr))}
.rs-tile{padding:14px;border-radius:14px;background:var(--g2);display:flex;flex-direction:column;gap:6px;min-width:0;position:relative}
.rs-tile.on{box-shadow:inset 0 0 0 2px var(--good)}.rs-tile.off{opacity:.5}
.rs-tile .k{font-size:12px;color:var(--t3)}
.rs-tile .big{font:800 22px/1 var(--sans)}
.rs-tile img.photo,.rs-tile .train-photo{width:100%;aspect-ratio:3/2;object-fit:cover;border-radius:10px;background:#2c2630}
.rs-rows{display:grid}
.rs-rows .r{display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-bottom:1px solid var(--g2);font-size:13px}
.rs-rows .r span{color:var(--t2)}.rs-rows .r b{font-family:var(--mono);font-weight:600;white-space:nowrap}
.rs-rows .r.total{border:0;font-size:15px}.rs-rows .r.total span{color:var(--t);font-weight:800}
.rs-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;height:40px;padding:0 16px;border-radius:12px;background:var(--g3);font-weight:800;font-size:13.5px;white-space:nowrap}
.rs-btn:hover{background:rgba(255,255,255,.18)}
.rs-btn.primary{background:var(--gold);color:#241a10}.rs-btn.primary:hover{filter:brightness(1.08)}
.rs-btn.danger{background:rgba(255,130,112,.16);color:var(--bad)}
.rs-btn[disabled]{opacity:.38;cursor:not-allowed}
.rs-foot{display:flex;gap:8px;justify-content:flex-end;align-items:center;margin-top:18px;flex-wrap:wrap}
.rs-foot .note{margin-right:auto;font-size:12px;color:var(--t3)}
.rs-note{font-size:12px;color:var(--t3)}
.rs-flag{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:10px;font-size:12.5px;font-weight:700;margin:4px 4px 0 0}
.rs-flag.ok{background:rgba(116,204,147,.14);color:var(--good)}.rs-flag.bad{background:rgba(255,130,112,.14);color:var(--bad)}.rs-flag.info{background:rgba(242,184,75,.14);color:var(--gold)}
.rs-spark{display:flex;align-items:flex-end;gap:3px;height:46px}
.rs-spark i{flex:1;max-width:20px;background:var(--gold);border-radius:3px 3px 0 0;min-height:2px;opacity:.85}.rs-spark i.n{background:var(--bad)}

/* planificadores */
.rs-modes{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:14px 0}
.rs-mode{padding:12px;border-radius:14px;background:var(--g2);text-align:left;display:flex;flex-direction:column;gap:6px}
.rs-mode:hover{background:var(--g3)}
.rs-mode.on{box-shadow:inset 0 0 0 2px var(--gold);background:rgba(242,184,75,.08)}
.rs-mode b{font-size:14px}.rs-mode span{font-size:12px;color:var(--t3)}
.rs-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:14px 0}
.rs-kpi b{display:block;font:800 19px/1.1 var(--sans);font-variant-numeric:tabular-nums;white-space:nowrap}
.rs-kpi span{display:block;font-size:11px;color:var(--t3);margin-top:3px}
.rs-phasebar{display:flex;gap:3px;margin:6px 0 2px}
.rs-phasebar div{height:26px;border-radius:7px;background:var(--g3);display:grid;place-items:center;font-size:11px;font-weight:700;color:var(--t2);min-width:34px}
.rs-phasebar div.build{background:rgba(242,184,75,.25);color:var(--gold)}
.rs-switch{display:flex;align-items:center;gap:10px;padding:8px 0;font-size:13px;color:var(--t2);cursor:pointer}
.rs-switch input{appearance:none;-webkit-appearance:none;width:34px;height:20px;border-radius:10px;background:var(--g3);position:relative;cursor:pointer;flex:none;transition:background .2s;margin:0}
.rs-switch input::after{content:"";position:absolute;top:3px;left:3px;width:14px;height:14px;border-radius:50%;background:#fff;transition:left .2s}
.rs-switch input:checked{background:var(--gold)}.rs-switch input:checked::after{left:17px}
.rs-switch.dark input:checked{background:var(--wine)}
.rs-field{display:grid;gap:6px;margin:10px 0}
.rs-field label{display:flex;justify-content:space-between;font-size:13px;color:var(--t2)}
.rs-field label b{color:var(--t);font-size:15px}
.rs-field input[type=range]{width:100%;accent-color:var(--gold)}

/* personajes */
.rs-talk{display:grid;grid-template-columns:150px 1fr;gap:18px;align-items:start}
.rs-talk img.face{width:150px;height:186px;object-fit:cover;border-radius:14px;box-shadow:0 10px 24px rgba(0,0,0,.4)}
.rs-talk .who{font-size:12px;color:var(--t3)}.rs-talk .who b{display:block;font-size:15px;color:var(--t)}
.rs-talk .say{font:500 18px/1.45 var(--serif);margin:8px 0 0;color:var(--t)}
.rs-talk .say.speaking{color:#ffe2a6}
.rs-replay{display:inline-flex;align-items:center;gap:6px;margin-top:8px;font-size:12px;font-weight:800;color:var(--gold)}
.rs-choices{display:grid;gap:6px;margin-top:18px}
.rs-choice{display:flex;align-items:center;gap:12px;width:100%;padding:13px 16px;border-radius:14px;background:var(--g2);text-align:left}
.rs-choice:hover{background:var(--g3)}
.rs-choice b{font-size:14.5px}.rs-choice span{margin-left:auto;font-size:12px;color:var(--t3);text-align:right}
.rs-choice.main{background:var(--gold);color:#241a10}.rs-choice.main span{color:#4a361a}
.rs-choice[disabled]{opacity:.4;cursor:not-allowed}
.rs-terms{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:16px}
.rs-terms div{font-size:12.5px;color:var(--t2)}
.rs-terms b{display:flex;align-items:center;gap:6px;font-size:10.5px;letter-spacing:1px;text-transform:uppercase;margin-bottom:4px}
.rs-terms .a b{color:var(--good)}.rs-terms .b b{color:var(--gold)}.rs-terms .c b{color:var(--blue)}.rs-terms .d b{color:var(--bad)}

/* árbol tecnológico */
.rs-tree{display:grid;grid-template-columns:repeat(6,minmax(150px,1fr));gap:12px;overflow-x:auto;padding-bottom:4px}
.rs-branch{display:grid;gap:10px;align-content:start}
.rs-branch h3{font:800 11px/1 var(--sans);letter-spacing:1.3px;text-transform:uppercase;color:var(--t3);text-align:center;margin-bottom:2px}
.rs-tech{position:relative;height:150px;border-radius:14px;overflow:hidden;background:linear-gradient(160deg,#3a3140,#1d1a22);text-align:left;display:flex;flex-direction:column;justify-content:flex-end;box-shadow:inset 0 0 0 1px rgba(255,255,255,.06)}
.rs-tech img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .4s}
.rs-tech:hover img{transform:scale(1.05)}
.rs-tech .ico{position:absolute;top:12px;left:12px;color:rgba(255,255,255,.3)}.rs-tech .ico svg.i{width:30px;height:30px}
.rs-tech .txt{position:relative;padding:28px 10px 10px;background:linear-gradient(transparent,rgba(10,8,12,.92) 45%)}
.rs-tech b{display:block;font-size:12.5px;line-height:1.2}
.rs-tech .price{display:flex;gap:8px;font:700 11px var(--mono);margin-top:5px;color:var(--gold)}
.rs-tech.owned{box-shadow:inset 0 0 0 2px var(--good)}.rs-tech.owned .price{color:var(--good)}
.rs-tech.locked img{filter:grayscale(1) brightness(.45)}.rs-tech.locked .txt{opacity:.6}
.rs-tech.ready{box-shadow:inset 0 0 0 2px var(--gold),0 0 20px rgba(242,184,75,.25)}
.rs-tech .lvl{position:absolute;top:8px;right:8px;padding:3px 7px;border-radius:7px;background:rgba(0,0,0,.55);font:800 10px var(--sans)}

/* megaproyectos */
.rs-megas{display:grid;gap:12px}
.rs-mega{display:grid;grid-template-columns:240px 1fr;gap:18px;padding:12px;border-radius:16px;background:var(--g2);align-items:center}
.rs-mega .pic{height:150px;border-radius:12px;overflow:hidden;background:linear-gradient(160deg,#3a3140,#1d1a22);display:grid;place-items:center;color:rgba(255,255,255,.25);position:relative}
.rs-mega .pic img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.rs-mega .pic svg.i{width:46px;height:46px}
.rs-pips{display:flex;gap:4px;margin:8px 0}
.rs-pips i{flex:1;height:6px;border-radius:3px;background:var(--g3)}.rs-pips i.done{background:var(--good)}.rs-pips i.on{background:var(--gold)}
.rs-needs{display:flex;gap:6px;flex-wrap:wrap;margin:8px 0}
.rs-need{padding:5px 9px;border-radius:999px;background:var(--g3);font-size:12px;color:var(--t2)}
.rs-need.ok{background:rgba(116,204,147,.15);color:var(--good)}

/* elecciones */
.rs-gauge{display:flex;align-items:center;gap:18px;margin:6px 0 18px}
.rs-gauge .big{font:800 54px/1 var(--sans)}
.rs-vote{flex:1;height:14px;border-radius:7px;background:var(--g3);position:relative;overflow:hidden}
.rs-vote i{position:absolute;inset:0 auto 0 0;background:linear-gradient(90deg,var(--wine),var(--gold));border-radius:7px}
.rs-vote::after{content:"";position:absolute;left:50%;top:-4px;bottom:-4px;width:2px;background:#fff}
.rs-groups{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.rs-groups .rs-tile ul{list-style:none;margin:6px 0 0;padding:0;display:grid;gap:3px;font-size:12px;color:var(--t2)}
.rs-groups li{display:flex;justify-content:space-between;gap:6px}

/* cloacas */
.rs-dark{--g2:rgba(196,70,109,.09);--g3:rgba(196,70,109,.2)}
.rs-meter{height:8px;border-radius:4px;background:var(--g3);overflow:hidden;margin:6px 0}.rs-meter i{display:block;height:100%;background:linear-gradient(90deg,var(--gold),var(--bad))}
.rs-steps{display:flex;gap:4px;margin:12px 0}.rs-steps span{flex:1;padding:7px 4px;border-radius:9px;background:var(--g2);font-size:11px;text-align:center;color:var(--t3)}
.rs-steps span.on{background:var(--bad);color:#fff}.rs-steps span.on:first-child{background:var(--good);color:#10301c}
.rs-bribe{display:flex;gap:12px;align-items:center}
.rs-bribe img{width:44px;height:44px;border-radius:50%;object-fit:cover;object-position:50% 20%;flex:none}

/* hitos */
.rs-track{display:flex;gap:8px;overflow-x:auto;padding-bottom:4px}
.rs-track .rs-tile{min-width:150px;flex:1}

/* tutorial */
.rs-coach{position:absolute;left:50%;bottom:80px;transform:translateX(-50%);width:min(560px,calc(100vw - 24px));display:flex;gap:14px;align-items:flex-start;padding:14px;z-index:30;animation:rs-in .3s ease}
.rs-coach img{width:64px;height:64px;border-radius:50%;object-fit:cover;object-position:50% 18%;flex:none;box-shadow:0 0 0 2px var(--gold)}
.rs-coach .who{font-size:11.5px;color:var(--t3)}.rs-coach .who b{color:var(--t)}
.rs-coach p{margin:3px 0 10px;font:500 15px/1.4 var(--serif)}
.rs-coach .row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.rs-coach .task{font-size:12.5px;font-weight:800;color:var(--gold)}
.rs-coach .skip{margin-left:auto;font-size:12px;color:var(--t3)}
.rs-coach .skip:hover{color:var(--t)}
.rs-modal .rs-coach{position:relative;left:auto;bottom:auto;transform:none;width:auto;margin:16px 24px 0;background:rgba(255,255,255,.05);box-shadow:none;animation:none}
.rs-focus{outline:3px solid var(--gold)!important;outline-offset:3px;animation:rs-pulse 1.3s infinite}
@keyframes rs-pulse{50%{outline-color:rgba(242,184,75,.25)}}
@keyframes rs-in{from{opacity:0;transform:translate(-50%,12px)}}
.rs-toast{position:fixed;left:50%;top:76px;transform:translateX(-50%);padding:10px 16px;border-radius:12px;background:#000d;color:#fff;font-weight:700;font-size:13.5px;z-index:60;max-width:calc(100vw - 24px);text-align:center;opacity:0;transition:opacity .25s;pointer-events:none}
.rs-toast.on{opacity:1}

@media (max-width:1180px){.rs-layers button span{display:none}.rs-ticker{display:none}}
@media (max-width:980px){.rs-res small{display:none}.rs-res button{padding:0 8px}}
/* móvil */
@media (max-width:760px){
 .rs{--top:112px}
 .rs-top{height:auto;flex-wrap:wrap;gap:4px 8px;padding:8px 8px 6px 12px;left:6px;right:6px;top:6px}
 .rs-res{order:3;width:100%;margin:0;justify-content:space-between;overflow-x:auto;scrollbar-width:none}
 .rs-res button{height:32px;padding:0 6px;gap:5px}.rs-res b{font-size:14px}
 .rs-iconbtn{margin-left:auto}
 .rs-rail{top:auto;bottom:70px;left:6px;right:6px;flex-direction:row;overflow-x:auto;scrollbar-width:none;justify-content:space-between}
 .rs-rail button{flex:none;width:40px;height:40px}.rs-rail button::after{display:none}
 .rs-mission{left:6px;right:6px;width:auto;top:var(--top);max-height:34vh;padding:12px}
 .rs-mission h2{font-size:18px;margin:6px 0 8px}
 .rs-side{left:6px;right:6px;width:auto;top:auto;bottom:126px;max-height:52vh}
 .rs-dock{left:6px;right:6px;bottom:6px;height:56px}
 .rs-layers button{padding:0 9px}
 .rs-next{padding:0 14px;font-size:14px}.rs-next .long{display:none}
 .rs-modes,.rs-kpis{grid-template-columns:1fr 1fr}
 .rs-terms{grid-template-columns:1fr 1fr}
 .rs-talk{grid-template-columns:84px 1fr;gap:12px}.rs-talk img.face{width:84px;height:104px}.rs-talk .say{font-size:16px}
 .rs-mega{grid-template-columns:1fr}.rs-mega .pic{height:120px}
 .rs-groups{grid-template-columns:1fr 1fr}
 .rs-tree{grid-template-columns:repeat(6,150px)}
 .rs-sheet>.inner{padding:18px 16px}
 .rs-coach{bottom:132px}
 .rs h1{font-size:23px}
}

.menu-preview-note{padding:9px 12px;margin:10px 0 15px;border:1px solid #cda85d66;border-radius:8px;background:#f8e7ba;color:#493019;font-size:12px;line-height:1.5;}
